def extract_messages(node):
  if isinstance(node,dict):
    m=node.get("messages")
    if isinstance(m,list) and (not m or isinstance(m[0],dict)): return m
    for v in node.values():
      out=extract_messages(v)
      if out: return out
  if isinstance(node,list):
    for v in node:
      out=extract_messages(v)
      if out: return out
  return []
